import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import type { WizardAnswers } from '@/types/wizard.types';
import { siteConfig } from '@/config/site.config';

const DEFAULT_ANSWERS: WizardAnswers = {
  mode: 'content-creation',
  outputLanguage: siteConfig.defaults.outputLanguage,
  aiModel: siteConfig.defaults.aiModel,
  lengthMode: siteConfig.defaults.lengthMode,
  promptFormat: siteConfig.defaults.promptFormat,
};

// ============================================================
// Context keys — كل ما يخص المهمة الحالية (يُمسح في كل جلسة)
// ============================================================
const CONTEXT_KEYS: (keyof WizardAnswers)[] = [
  // Content creation
  'contentType',
  'niche',
  'nicheCustom',
  'topic',
  'audience',
  'audienceCustom',
  'goal',
  'goalCustom',
  'painPoint',
  'painPointCustom',
  'platform',
  'platformCustom',
  'ctaType',
  'ctaTypeCustom',
  'tone',
  'toneCustom',
  'duration',
  'hookStyle',
  'wordCount',
  // Learn skill
  'skillTermId',
  'depthLevel',
  // Channel strategy
  'channelPlatform',
  'channelPlatformCustom',
  'channelNiche',
  'channelNicheCustom',
  'channelGoal',
  'channelStatus',
  'presentationStyle',
  // Idea evaluation
  'ideaText',
  'ideaNiche',
  'ideaNicheCustom',
  'ideaContentType',
  'ideaContentTypeCustom',
  'evaluationStrictness',
  // Custom
  'customTermIds',
  // Extra
  'additionalNotes',
];

interface WizardState {
  answers: WizardAnswers;
  currentStep: number;
  sessionId: string;          // ← جديد — يتبدل مع كل جلسة
  setAnswer: <K extends keyof WizardAnswers>(key: K, value: WizardAnswers[K]) => void;
  setAnswers: (patch: Partial<WizardAnswers>) => void;
  reset: () => void;
  resetContext: () => void;   // ← جديد — يمسح السياق فقط
  startNewSession: () => void; // ← جديد — يمسح السياق ويولّد sessionId
  setStep: (step: number) => void;
  nextStep: () => void;
  prevStep: () => void;
}

export const useWizardStore = create<WizardState>()(
  persist(
    (set) => ({
      answers: { ...DEFAULT_ANSWERS },
      currentStep: 0,
      sessionId: crypto.randomUUID(),

      setAnswer: (key, value) =>
        set((s) => ({ answers: { ...s.answers, [key]: value } })),

      setAnswers: (patch) =>
        set((s) => ({ answers: { ...s.answers, ...patch } })),

      reset: () =>
        set({ answers: { ...DEFAULT_ANSWERS }, currentStep: 0 }),

      resetContext: () =>
        set((s) => {
          const newAnswers = { ...s.answers };
          for (const key of CONTEXT_KEYS) {
            delete newAnswers[key];
          }
          // احتفظ فقط بالإعدادات
          newAnswers.mode = s.answers.mode;
          newAnswers.aiModel = s.answers.aiModel;
          newAnswers.lengthMode = s.answers.lengthMode;
          newAnswers.outputLanguage = s.answers.outputLanguage;
          newAnswers.promptFormat = s.answers.promptFormat;
          return { answers: newAnswers, currentStep: 0 };
        }),

      startNewSession: () =>
        set((s) => {
          const newAnswers = { ...s.answers };
          for (const key of CONTEXT_KEYS) {
            delete newAnswers[key];
          }
          newAnswers.mode = s.answers.mode;
          newAnswers.aiModel = s.answers.aiModel;
          newAnswers.lengthMode = s.answers.lengthMode;
          newAnswers.outputLanguage = s.answers.outputLanguage;
          newAnswers.promptFormat = s.answers.promptFormat;
          return {
            answers: newAnswers,
            currentStep: 0,
            sessionId: crypto.randomUUID(),
          };
        }),

      setStep: (step) => set({ currentStep: step }),
      nextStep: () => set((s) => ({ currentStep: s.currentStep + 1 })),
      prevStep: () => set((s) => ({ currentStep: Math.max(0, s.currentStep - 1) })),
    }),
    {
      name: 'prompt-dna-wizard',
      storage: createJSONStorage(() => localStorage),
    },
  ),
);